+  fb->pinfo.stride = BOARD_VELAPOKA_LCD_WIDTH * 2;
+  fb->pinfo.fblen = (size_t)fb->pinfo.stride *
+                    BOARD_VELAPOKA_LCD_HEIGHT * 2;
+  fb->pinfo.display = 0;
+  fb->pinfo.bpp = 16;
+  fb->pinfo.xres_virtual = BOARD_VELAPOKA_LCD_WIDTH;
+  fb->pinfo.yres_virtual = BOARD_VELAPOKA_LCD_HEIGHT * 2;
+  fb->frame_length = (size_t)fb->pinfo.stride *
