 *   queue - Queue handle.
 *   item  - Pointer to the buffer to receive the item.
 *   ticks - Ticks to wait.
 *
 * Returned Value:
 *   ESP_OK on success; ESP_FAIL on failure.
 *
 ****************************************************************************/

static esp_err_t esp_os_queue_receive_generic(esp_os_queue_handle_t queue,
                                              FAR void *item,
                                              uint32_t ticks)
{
  ssize_t ret;
  struct timespec timeout;
  unsigned int prio;
  FAR struct mq_adpt *mq_adpt = (FAR struct mq_adpt *)queue;

  if (ticks == OS_PORT_MAX_DELAY || up_interrupt_context())
    {
      ret = file_mq_receive(&mq_adpt->mq, (FAR char *)item,
                            mq_adpt->msgsize, &prio);
      if (ret < 0 && ret != -EAGAIN)
        {
          _err("Failed to receive from mqueue error=%d\n", ret);
        }
    }
  else
    {
      ret = clock_gettime(CLOCK_REALTIME, &timeout);
      if (ret < 0)
        {
          _err("Failed to get time\n");
          return false;
        }

      if (ticks)
        {
          struct timespec ts;

          clock_ticks2time(&ts, ticks);
          clock_timespec_add(&timeout, &ts, &timeout);
        }

      ret = file_mq_timedreceive(&mq_adpt->mq, (FAR char *)item,
                                 mq_adpt->msgsize, &prio, &timeout);
      if (ret < 0 && ret != -EAGAIN)
        {
          _err("Failed to timedreceive from mqueue error=%d\n", ret);
        }
    }

  return ret >= 0 ? ESP_OK : ESP_FAIL;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

static int esp_os_intr_adapter(int irq, FAR void *context, FAR void *arg)
{
  FAR esp_os_intr_handle_t *handle = arg;

  if (handle->status_reg == 0 ||
      (*(volatile uint32_t *)(uintptr_t)handle->status_reg &
       handle->status_mask) != 0)
    {
      handle->handler(handle->arg);
    }

  return OK;
}

esp_err_t esp_os_intr_free(intr_handle_t handle)
{
  FAR esp_os_intr_handle_t *adapter = (FAR esp_os_intr_handle_t *)handle;

  if (adapter == NULL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  up_disable_irq(adapter->irq);
  irq_detach(adapter->irq);
  esp_teardown_irq(adapter->source, adapter->cpuint);
  kmm_free(adapter);
  return ESP_OK;
}

/* The ESP timer implementation calls the public interrupt-control API
 * directly after allocating through esp_os_intr_alloc().  The native IDF
 * interrupt allocator is not linked on NuttX, so operate on the adapter
 * handle created above.
 */

esp_err_t esp_intr_enable(intr_handle_t handle)
{
  FAR esp_os_intr_handle_t *adapter = (FAR esp_os_intr_handle_t *)handle;

  if (adapter == NULL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  up_enable_irq(adapter->irq);
  return ESP_OK;
}

esp_err_t esp_intr_disable(intr_handle_t handle)
{
  FAR esp_os_intr_handle_t *adapter = (FAR esp_os_intr_handle_t *)handle;

  if (adapter == NULL)
    {
      return ESP_ERR_INVALID_ARG;
    }

  up_disable_irq(adapter->irq);
  return ESP_OK;
}

/****************************************************************************
 * Name: esp_os_intr_alloc
 *
 * Description:
 *   Allocate an interrupt handler.
 *
 * Input Parameters:
 *   source     - Interrupt source.
 *   flags      - Interrupt flags.
 *   handler    - Interrupt handler function.
 *   arg        - User argument.
 *   ret_handle - Pointer to receive the interrupt handle.
 *
 * Returned Value:
 *   ESP_OK on success; error code on failure.
 *
 ****************************************************************************/

esp_err_t esp_os_intr_alloc(int source, int flags,
                             esp_os_intr_handler_t handler, FAR void *arg,
                             FAR intr_handle_t *ret_handle)
{
  return esp_os_intr_alloc_intrstatus(source, flags, 0, 0, handler, arg,
                                      ret_handle);
}
