esp_err_t esp_intr_alloc_intrstatus_bind(int source, int flags, uint32_t intrstatusreg, uint32_t intrstatusmask, intr_handler_t handler,
                                    void *arg, intr_handle_t shared_handle, intr_handle_t *ret_handle)
{
