            esp_os_exit_critical_safe(&spinlock);
            return ESP_ERR_INVALID_ARG; //Can only enable these ints on this cpu
        }
        ESP_INTR_ENABLE(handle->vector_desc->intno);
    }
    esp_os_exit_critical_safe(&spinlock);
    return ESP_OK;
}

