#define CAMTEST_PREVIEW_GAIN    4

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct camtest_buffer_s
{
  FAR uint8_t *data;
};

struct camtest_fb_s
{
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  FAR uint8_t *memory;
  int fd;
  unsigned int draw_buffer;
};

/****************************************************************************
 * Private Functions
