  syslog(LOG_INFO, "SC2336 DW-GDMA: cfg=%08lx chen=%08lx int=%08lx\n",
         (unsigned long)dma->cfg0.val,
         (unsigned long)dma->chen0.val,
         (unsigned long)dma->int_st0.val);
