  format.fmt.pix.width = CAMTEST_WIDTH;
  format.fmt.pix.height = CAMTEST_HEIGHT;
  format.fmt.pix.field = V4L2_FIELD_ANY;
  format.fmt.pix.pixelformat = V4L2_PIX_FMT_SBGGR10P;
  if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&format) < 0)
